import itertools, json, sys
from problems import ThreeColoring, ThreeSat
from reduce import reduce

def solve_three_coloring(instance):
    n = instance['n']
    edges = instance['edges']
    # colors 0,1,2
    for assign in itertools.product(range(3), repeat=n):
        ok = True
        for u, v in edges:
            if assign[u] == assign[v]:
                ok = False
                break
        if ok:
            return True
    return False

def solve_three_sat(instance):
    m = instance['num_vars']
    clauses = instance['clauses']
    for vals in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            # clause is list of three literals
            sat = False
            for lit in clause:
                var = abs(lit) - 1
                sign = lit > 0
                if vals[var] == sign:
                    sat = True
                    break
            if not sat:
                ok = False
                break
        if ok:
            return True
    return False

def generate_graphs(max_n):
    for n in range(max_n+1):
        vertices = list(range(n))
        possible_edges = [(i,j) for i in vertices for j in vertices if i<j]
        for mask in range(1<<len(possible_edges)):
            edges = []
            for idx, (u,v) in enumerate(possible_edges):
                if mask>>idx & 1:
                    edges.append([u,v])
            yield {'n': n, 'edges': edges}

def main():
    total = 0
    passed = 0
    for instance in generate_graphs(4):
        total += 1
        ThreeColoring.validate(instance)
        ans_col = solve_three_coloring(instance)
        red = reduce(instance)
        ThreeSat.validate(red)
        ans_sat = solve_three_sat(red)
        if ans_col == ans_sat:
            passed += 1
        else:
            print('Mismatch', instance, ans_col, ans_sat, file=sys.stderr)
            break
    verdict = {'verified': passed==total, 'tests_run': total, 'tests_passed': passed}
    with open('verdict.json','w') as f:
        json.dump(verdict, f)
    print(json.dumps(verdict))

if __name__ == '__main__':
    main()
EOF"}

